/// 🧳️ The public handle moves only its pointer; the separately admitted frame keeps original source custody.
pub struct ArtifactNativeVcsCommand<P,M:Mutation<P>>{pub(super) frame:ManuallyDrop<Option<Box<ArtifactNativeVcsFrame<P,M>>>>}
fn native_vcs_refusal(reason:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,reason)}
fn native_vcs_header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn native_vcs_progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
