 /// 🧭️ Reports the real phase without implying unpublished metadata is complete.
 pub fn phase(&self)->ArtifactNativeVcsPhase{self.frame.as_ref().map_or(ArtifactNativeVcsPhase::Complete,|frame|frame.phase)}
 /// 🎟️ Preserves the original operation identity across every turn and source loan.
