 pub fn candidate(&self)->Option<&P>{self.frame.as_ref()?.candidate.as_deref()}
 /// 📬️ Borrows only the result sealed by actual Store publication.
 pub fn borrow_result(&self)->Option<&ArtifactNativeVcsResult>{self.frame.as_ref()?.result.as_ref()}
 /// 🫙️ Terminal ownership includes the separately funded frame release.
 pub fn terminal_is_empty(&self)->bool{self.frame.is_none()}
